# launch_clearance.py
# if / elif / else with comparison and logical operators

fuel = int(input("Fuel level (0-100): "))
weather = input("Weather (clear/windy/storm): ").lower()
crew_ready = input("Is the crew ready? (yes/no): ").lower() == "yes"

print()
if fuel < 20:
    print("ABORT: not enough fuel.")
elif weather == "storm":
    print("HOLD: storm over the launch pad.")
elif weather == "windy" and fuel < 60:
    print("HOLD: windy weather needs at least 60 percent fuel.")
else:
    if crew_ready:
        print("GO FOR LAUNCH!")
    else:
        print("HOLD: waiting for the crew.")

# Combining conditions
if fuel >= 90 and weather == "clear":
    print("Bonus: perfect launch window.")
if not crew_ready or fuel < 50:
    print("Reminder: run the pre-flight checklist again.")

# safe_console.py
# try / except / else / finally, validation and raise

def read_number(prompt, low, high):
    """Keep asking until the user types a whole number from low to high."""
    while True:
        text = input(prompt)
        try:
            number = int(text)
        except ValueError:
            print("  That is not a whole number. Try again.")
            continue
        if number < low or number > high:
            print(f"  Please choose a number from {low} to {high}.")
            continue
        return number

def safe_divide(a, b):
    """Divide a by b, returning None when b is zero."""
    try:
        result = a / b
    except ZeroDivisionError:
        print("  Cannot divide by zero.")
        return None
    else:
        return result
    finally:
        print("  (division attempted)")

def validate_callsign(callsign):
    """Return the callsign in capitals, or raise ValueError."""
    if len(callsign) < 3:
        raise ValueError("a callsign needs at least 3 characters")
    if not callsign.isalnum():
        raise ValueError("a callsign may only contain letters and digits")
    return callsign.upper()

crew = read_number("Crew size (1-6): ", 1, 6)
print("Crew size accepted:", crew)

print(safe_divide(10, 4))
print(safe_divide(10, 0))

for attempt in ["nova7", "ab", "no va!"]:
    try:
        print("Accepted:", validate_callsign(attempt))
    except ValueError as error:
        print("Rejected:", attempt, "->", error)

cargo = {"oxygen": 5}
try:
    print(cargo["medkit"])
except KeyError as error:
    print("Missing cargo item:", error)
